#!/usr/bin/env python3
"""Build an offline before/after review. Keep generation failures visible."""
import argparse,json
from pathlib import Path
p=argparse.ArgumentParser(description=__doc__)
p.add_argument('--before',required=True);p.add_argument('--after',required=True);p.add_argument('--control')
a=p.parse_args();before=Path(a.before);after=Path(a.after)
old=json.loads((before/'results.json').read_text());new=json.loads((after/'results.json').read_text())
controls=json.loads((Path(a.control)/'results.json').read_text()) if a.control else []
oldmap={(r['cardId'],r['level']):r for r in old};controlmap={(r['cardId'],r['level']):r for r in controls}
notes=json.loads((after/'review.json').read_text()) if (after/'review.json').exists() else {}
ratings=json.loads((before/'human-review.json').read_text()).get('ratings',{}) if (before/'human-review.json').exists() else {}
pairs=[{'before':oldmap[r['cardId'],r['level']],'after':r,'spellingControl':controlmap.get((r['cardId'],r['level'])),'afterReview':notes.get(r['caseId']),'humanReview':ratings.get(oldmap[r['cardId'],r['level']]['caseId'])} for r in sorted(new,key=lambda r:(int(r['caseId'][1:3]),['easy','medium','hard'].index(r['level'])))]
answers=[x for r in new+controls for x in r.get('attempts',[])]
summary={'originalTasks':len(new),'generated':sum(bool(r.get('source')) for r in new),'generationFailures':[r['caseId'] for r in new if r.get('generationError')],'spellingControls':len(controls),'completed':sum(bool(r.get('complete')) for r in new+controls),'answers':len(answers),'unexpectedTestExpectations':[{'caseId':r['caseId'],'kind':x['kind'],'accepted':x.get('accepted'),'expected':x['expectedAccepted']} for r in new+controls for x in r.get('attempts',[]) if x.get('accepted')!=x['expectedAccepted']],'thumbsUp':sum('👍' in x.get('feedback','') for x in answers)}
d={'summary':summary,'manifest':json.loads((after/'manifest.json').read_text()),'pairs':pairs}
(after/'comparison.json').write_text(json.dumps(d,ensure_ascii=False,indent=2))
t='''<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ben is Back I · Vorher und nachher</title><style>
:root{font:16px/1.55 system-ui,sans-serif;color:#24362c;background:#f3f5ee}*{box-sizing:border-box}body{margin:0}header,main{max-width:1550px;margin:auto;padding:25px}h1{font-size:36px;margin:8px 0}h2{margin:28px 0 10px}h3{font-size:17px;margin:0}.kicker{font-size:13px;font-weight:750;letter-spacing:.07em;color:#537456;text-transform:uppercase}.intro{max-width:1080px}.metrics{display:flex;flex-wrap:wrap;gap:12px;margin:20px 0}.metric{border:1px solid #d8e1d3;background:white;padding:12px 20px;border-radius:12px}.metric b{display:block;font-size:26px}.filters{position:sticky;top:0;display:flex;gap:12px;padding:14px 0;background:#f3f5eef5;z-index:2}input,select,button{font:inherit;border:1px solid #bacaaf;border-radius:8px;padding:10px;background:#fff}input{flex:1;min-width:120px}button{cursor:pointer}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px}.task{background:white;border:1px solid #d6e0ce;border-radius:14px;padding:20px;min-width:0}.label{font-size:12px;font-weight:750;color:#58744e}.old{color:#637064;padding:12px 0;border-bottom:1px solid #e2e8dc}.new{font-size:19px;padding:12px 0}.note{font-size:14px;padding:12px;background:#fff4dd;border-left:3px solid #c79e53}.human{font-size:14px;background:#e9f0e2;padding:12px}.muted{color:#647460;font-size:14px}.answer{background:#f3f5ee;padding:10px;border-radius:7px;white-space:pre-wrap}.attempt{padding:10px 0;border-top:1px solid #dfe6d8}code{font:inherit;font-style:italic;font-weight:650}details{margin:15px 0}summary{cursor:pointer;font-weight:650}li{margin:7px 0}.help{background:#edf3e5;padding:10px;border-radius:7px}.state{font-size:12px;font-weight:750;color:#50784b}mark{background:#e4edcf}.tablewrap{overflow:auto}p{margin:8px 0 13px}a{color:#315d41}@media(max-width:1000px){.grid{grid-template-columns:1fr}header,main{padding:17px}h1{font-size:29px}}
</style><header><div class="kicker">Ben is Back I · neue Prompts · Sichtung 2</div><h1>Neue Sätze und Rückmeldungen vergleichen</h1><p class="intro">Terra 6.1, durchgehend medium. Pro Stufe steht oben der bisherige Satz, darunter der neue. Die neue Quelle bleibt bei der Feedbackprüfung unverändert. Dies ist ein Kandidatenstand; noch kein produktiver Rollout.</p><div class="metrics" id="metrics"></div><div class="intro"><p><b>Was sich geändert hat:</b> Einfach ohne zusätzliche Lernhürde, Mittel mit einer bekannten Grundgrammatikanforderung, Schwer mit einem überschaubaren Muster für starke Lernende der Klassen 9/10. Kurze persönliche Einleitung, konkrete Diagnose im Fehlerpunkt, gezielte Emojis.</p><p><b>Offen geblieben:</b> Der Set-Tippfehler Umkleiderraum blockiert drei Originalaufgaben. Separat gezeigte Kontrollen verwenden eine ausdrücklich korrigierte Testkopie. Keine Lockerung der Validierung und keine Änderung am Originalset.</p><p><b>Eine offene Testannahme:</b> suspiciously wurde zur Zielvokabel suspicious angenommen. Das ist für die Wortformbindung und eine direkte einfache Übersetzung weiter zu klären. Die Anmerkungen an den Fällen halten zusätzliche inhaltliche Grenzen fest.</p><details><summary>Methode und Grenzen</summary><p>42 identische Vokabelpaare auf drei Stufen. Alte und neue Sätze sind verschieden, deshalb ist dies kein exakter A/B-Test des Feedbacks bei identischen Eingaben. Neue Schülerantworten sind vom Assistenten anhand der tatsächlichen Quellen formulierte Testdaten. Abweichungen von den Testannahmen müssen inhaltlich eingeordnet werden. Beide Datensätze und die menschliche Review-Matrix bleiben erhalten.</p><p>Ein erster Zwischenstand machte Mittel zu leicht; der aktuelle Stand verlangt dort gezielt eine bekannte Anforderung. Die Zwischenläufe sind getrennt archiviert und nicht in den Endergebnissen vermischt.</p></details><button id="download">Vergleich als JSON herunterladen</button></div></header><main><div class="filters"><input id="search" aria-label="Suchen" placeholder="Vokabel oder Satz suchen …"><select id="level" aria-label="Stufe"><option value="all">Alle drei Stufen</option><option value="easy">Einfach</option><option value="medium">Mittel</option><option value="hard">Schwer</option></select></div><p id="count" class="muted"></p><div id="records"></div></main><script id="data" type="application/json">__DATA__</script><script>
const D=JSON.parse(document.getElementById('data').textContent),$=s=>document.querySelector(s),names={easy:'Einfach',medium:'Mittel',hard:'Schwer'};const el=(t,s,c)=>{const e=document.createElement(t);if(s!==undefined)e.textContent=s;if(c)e.className=c;return e};function rich(s){const e=el('span');String(s||'').split('`').forEach((x,i)=>e.append(el(i%2?'code':'span',x)));return e}
for(const [n,s]of[[42,'Vokabeln'],[D.summary.originalTasks,'Originalversuche'],[D.summary.generated,'direkt erzeugt'],[D.summary.spellingControls,'separate Tippfehlerkontrollen'],[D.summary.answers,'geprüfte Antworten']]){const m=el('div',undefined,'metric');m.append(el('b',n),el('span',s));$('#metrics').append(m)}
function history(record,label){const details=el('details');details.append(el('summary',label));for(const a of record.attempts||[]){const box=el('div',undefined,'attempt');box.append(el('p',a.answer,'answer'),el('span',a.error?'Technischer Fehler':a.accepted?'Angenommen':'Überarbeiten','state'));const p=el('p');p.append(rich(a.feedback||a.error?.message));box.append(p);if(a.issues?.length){const ul=el('ul');for(const i of a.issues){const li=el('li');if(i.quote!==null)li.append(el('b',i.quote+' — '));li.append(rich(i.message));ul.append(li)}box.append(ul)}if(a.help){const h=el('div',undefined,'help');h.append(rich(a.help.explanation));if(a.help.example)h.append(el('p',a.help.example));box.append(h)}details.append(box)}return details}
function render(){const q=$('#search').value.toLowerCase(),level=$('#level').value;$('#records').replaceChildren();const groups=new Map;let count=0;for(const p of D.pairs){if(level!=='all'&&p.after.level!==level)continue;if(q&&!JSON.stringify(p).toLowerCase().includes(q))continue;if(!groups.has(p.after.cardId))groups.set(p.after.cardId,[]);groups.get(p.after.cardId).push(p);count++}for(const group of groups.values()){const section=el('section');section.append(el('h2',group[0].after.en+' ↔ '+group[0].after.de));const grid=el('div',undefined,'grid');for(const p of group){const card=el('article',undefined,'task');card.append(el('h3',names[p.after.level]));card.append(el('div','BISHER','label'),el('p',p.before.source,'old'),el('div','NEU','label'));if(p.after.generationError){card.append(el('p','Originalaufgabe blockiert: '+p.after.generationError.message,'note'));if(p.spellingControl){card.append(el('p','Separate Kontrolle mit Umkleideraum statt Umkleiderraum:','muted'),el('p',p.spellingControl.source,'new'));card.append(history(p.spellingControl,'Feedback der korrigierten Testkopie'))}}else{card.append(el('p',p.after.source,'new'));card.append(history(p.after,'Neues Feedback · '+(p.after.attempts||[]).length+' Abgaben'))}if(p.afterReview)card.append(el('p',p.afterReview,'note'));card.append(history(p.before,'Bisheriges Feedback'));if(p.humanReview?.comment){const d=el('details');d.append(el('summary','Dein Kommentar zum bisherigen Fall'),el('p',p.humanReview.comment,'human'));card.append(d)}grid.append(card)}section.append(grid);$('#records').append(section)}$('#count').textContent=count+' von '+D.pairs.length+' Vergleichsfällen.'}
$('#search').addEventListener('input',render);$('#level').addEventListener('change',render);$('#download').addEventListener('click',()=>{const u=URL.createObjectURL(new Blob([JSON.stringify(D,null,2)],{type:'application/json'}));const a=el('a');a.href=u;a.download='ben-is-back-vergleich-v2.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)});render();
</script></html>'''
encoded=json.dumps(d,ensure_ascii=False).replace('<','\\u003c').replace('\u2028','\\u2028').replace('\u2029','\\u2029')
(after/'comparison.html').write_text(t.replace('__DATA__',encoded));print(json.dumps(summary,ensure_ascii=False))
